import{_ as a,o as d,c as r,a2 as e}from"./chunks/framework.CqpfiAoK.js";const c=JSON.parse('{"title":"قواعد العبور بين الأبعاد","description":"","frontmatter":{},"headers":[],"relativePath":"ar/81-位面穿梭规则.md","filePath":"ar/81-位面穿梭规则.md"}'),l={name:"ar/81-位面穿梭规则.md"};function i(o,t,h,n,s,p){return d(),r("div",null,[...t[0]||(t[0]=[e('<h1 id="قواعد-العبور-بين-الأبعاد" tabindex="-1">قواعد العبور بين الأبعاد <a class="header-anchor" href="#قواعد-العبور-بين-الأبعاد" aria-label="Permalink to &quot;قواعد العبور بين الأبعاد&quot;">​</a></h1><table tabindex="0"><thead><tr><th>العنصر</th><th>المحتوى</th></tr></thead><tbody><tr><td>رقم الوثيقة</td><td>81</td></tr><tr><td>الوحدة</td><td>التفاعل عبر الأبعاد وقواعد الزمن</td></tr><tr><td>الكلمات المفتاحية</td><td>العبور بين الأبعاد، تصاريح العبور، عتبات الطاقة، معايرة المرساة، الوقاية من التلوث وضبطه</td></tr></tbody></table><h2 id="أولاً-التموضع-القانوني-للعبور" tabindex="-1">أولاً: التموضع القانوني للعبور <a class="header-anchor" href="#أولاً-التموضع-القانوني-للعبور" aria-label="Permalink to &quot;أولاً: التموضع القانوني للعبور&quot;">​</a></h2><p>العبور بين الأبعاد هو سلوك يعبر فيه فرد أو جماعة من الكائنات الحية حاجز القوانين ليدخل من بُعد إلى آخر، بوسائل تقنية أو بقدرات الزراعة. في إطار القانوني لحضارة التكافل المرساة، يُصنف العبور بين الأبعاد ضمن «السلوك الخاص عالي الخطورة»، ويجب أن يخضع لإدارة صارمة للتصاريح وإشراف على سير العملية. تنص المادة 47 من الدستور التكافلي بوضوح: «لا يجوز لأي منظمة أو فرد القيام بالعبور عبر الأبعاد دون تصريح، ولا يجوز استخدام العبور بين الأبعاد في أنشطة الافتراس أو التدخل أو التلويث ضد حضارة أبعاد أخرى.»</p><p>السبب الجذري لضرورة الضبط الصارم للعبور هو أن سلوك العبور نفسه قد يحدث تأثيرات متعددة على البُعد المستهدف: اضطراب القوانين، وحقن الطاقة، وتلوث الوعي، وغزو الأحياء الدقيقة، والتدخل الثقافي. هذه التأثيرات قد تسبب في أدنى حالاتها شذوذاً محلياً في البُعد المستهدف، وفي أسوأها قد تغير مسار تطوره الحضاري، بل وتؤدي إلى انهيار قوانينه. لذلك، الهدف الجوهري لقواعد العبور هو «إبقاء التأثير الخارجي لسلوك العبور ضمن عتبة مقبولة».</p><h2 id="ثانياً-نظام-تصنيف-تصاريح-العبور" tabindex="-1">ثانياً: نظام تصنيف تصاريح العبور <a class="header-anchor" href="#ثانياً-نظام-تصنيف-تصاريح-العبور" aria-label="Permalink to &quot;ثانياً: نظام تصنيف تصاريح العبور&quot;">​</a></h2><p>يطبق كون هنغ يوان نظام تصنيف لتصاريح العبور بين الأبعاد، يقسم التصاريح إلى أربعة مستويات وفقاً لغرض العبور ونوع البُعد المستهدف ومؤهلات العابر:</p><table tabindex="0"><thead><tr><th>مستوى التصريح</th><th>السيناريو المطبق</th><th>جهة الموافقة</th><th>الصلاحية</th><th>الشروط الإضافية</th></tr></thead><tbody><tr><td>المستوى أ (الملاحظة الأثرية)</td><td>آثار رصدية بحتة، دون أي اتصال فيزيائي</td><td>إدارة الأبعاد</td><td>مهمة واحدة</td><td>يجب اعتماد مخطط مرآة النسخ + الفضاء المعزول</td></tr><tr><td>المستوى ب (التبادل الأكاديمي)</td><td>تبادل معرفي محدود مع حضارة البُعد المستهدف</td><td>إدارة الأبعاد + وزارة الثقافة</td><td>سنة كحد أقصى</td><td>يجب توقيع اتفاق عدم التدخل المتبادل</td></tr><tr><td>المستوى ج (التعاون في الموارد)</td><td>تعاون في الموارد والتقنية على أساس المساواة والمنفعة المتبادلة</td><td>موافقة خاصة من المجلس التشريعي للمرساة</td><td>ثلاث سنوات كحد أقصى</td><td>يجب الحصول على موافقة حضارة البُعد المستهدف</td></tr><tr><td>المستوى د (التدخل الطارئ)</td><td>تدخل إنساني عندما يواجه البُعد المستهدف أزمة من مستوى الانقراض</td><td>قرار طارئ من المجلس التشريعي للمرساة</td><td>فترة الأزمة</td><td>يجب تقديم تقرير تدخل كامل بعد ذلك</td></tr></tbody></table><p>تحظر تصاريح العبور من أي مستوى السلوكيات التالية: نهب الطاقة الأصلانية للبُعد المستهدف، وفرض أيديولوجية البُعد الخاص قسراً، وإجراء تعديلات جينية أو وعيوية دون موافقة، وإنشاء قواعد عسكرية دائمة في البُعد المستهدف، وأي شكل من أشكال الهيمنة الاستعمارية.</p><h2 id="ثالثاً-المتطلبات-التقنية-وعتبات-الطاقة-للعبور" tabindex="-1">ثالثاً: المتطلبات التقنية وعتبات الطاقة للعبور <a class="header-anchor" href="#ثالثاً-المتطلبات-التقنية-وعتبات-الطاقة-للعبور" aria-label="Permalink to &quot;ثالثاً: المتطلبات التقنية وعتبات الطاقة للعبور&quot;">​</a></h2><p>يجب أن يستوفي العبور بين الأبعاد شروطاً تقنية صارمة. أولاً، يجب أن يمتلك العابر زراعة تفوق المستوى الثالث (مرحلة هواكونغ) من «نظام تسيير المبادئ القانونية المكانية»، أو أن يركب مركبة عبور بين الأبعاد مطابقة للمعايير. ثانياً، يجب أن تتوفر مرساة في نقطة الانطلاق ونقطة الوصول معاً لمعايرة الإحداثيات؛ ويُحظر تماماً العبور الأعمى دون تحديد بالمرساة.</p><p>يتناسب استهلاك الطاقة لعملية العبور طرداً مع قوة حاجز القوانين للبُعد المستهدف. أنشأ كون هنغ يوان «جدول عتبات طاقة العبور» معيارياً، والطاقة الدنيا المطلوبة للعبور إلى الأنواع المختلفة من الأبعاد هي:</p><ul><li>بُعد هيمنة المادة: 1000 وحدة طاقة قياسية</li><li>بُعد الطاقة المتجلية: 5000 وحدة طاقة قياسية</li><li>بُعد هيمنة الوعي: 20000 وحدة طاقة قياسية</li><li>بُعد القوانين المفتتة: 50000 وحدة طاقة قياسية (مع نسبة نجاح تقل عن 30٪)</li><li>البُعد القريب من الأصل: قيمة نظرية تزيد عن 100000، لا يوجد سجل نجاح حتى الآن</li></ul><p>يجب أن يحمل العابر أو المركبة طاقة العبور بنفسهما؛ ويُحظر سحب الطاقة من البُعد المستهدف لعملية العبور. ويهدف هذا الحكم إلى منع سلوك العبور من إحداث نهب للطاقة على البُعد المستهدف.</p><h2 id="رابعاً-الوقاية-من-التلوث-وضبطه-في-عملية-العبور" tabindex="-1">رابعاً: الوقاية من التلوث وضبطه في عملية العبور <a class="header-anchor" href="#رابعاً-الوقاية-من-التلوث-وضبطه-في-عملية-العبور" aria-label="Permalink to &quot;رابعاً: الوقاية من التلوث وضبطه في عملية العبور&quot;">​</a></h2><p>من أكبر مخاطر العبور بين الأبعاد «التلوث عبر الأبعاد»، ويشمل التلوث البيولوجي (نقل أحياء دقيقة من البُعد الخاص إلى البُعد المستهدف)، والتلوث الطاقي (تدخل بقايا طاقة البُعد الخاص في قوانين البُعد المستهدف)، وتلوث الوعي (تأثير تموجات وعي العابر في مجال الوعي للبُعد المستهدف).</p><p>للوقاية من التلوث وضبطه، يجب على جميع العابرين إكمال «إجراء التنقية بثلاثة مستويات» قبل الانطلاق:</p><ol><li><strong>التنقية البيولوجية</strong>: إجراء فحص وإزالة للأحياء الدقيقة لمدة 72 ساعة في الفضاء المعزول، لضمان عدم حمل أي ممرض من البُعد الخاص.</li><li><strong>تنقية الطاقة</strong>: ضبط تردد طاقة العابر إلى نطاق متوافق مع البُعد المستهدف عبر جهاز معايرة المرساة، تقليلاً لتفاعلات التنافر الطاقي.</li><li><strong>تنقية الوعي</strong>: الخضوع لتدريب حجب الوعي، لضمان عدم إطلاق تموجات فكرية قد تتدخل في مجال الوعي للبُعد المستهدف خلال العبور.</li></ol><p>بالإضافة إلى ذلك، يُقيَّد نطاق نشاط العابر في البُعد المستهدف بشدة ضمن «المنطقة المحددة في تصريح العبور»، ويُحظر الانتشار دون إذن. وبعد العودة إلى البُعد الخاص، يجب أن يخضع العابر مرة أخرى لملاحظة العزل، لمدة لا تقل عن 30 يوماً محسوبة بتحويل سرعة زمن البُعد المستهدف.</p><h2 id="الخلاصة" tabindex="-1">الخلاصة <a class="header-anchor" href="#الخلاصة" aria-label="Permalink to &quot;الخلاصة&quot;">​</a></h2><p>قواعد العبور بين الأبعاد هي خط الدفاع الأول لسلامة التفاعل عبر الأبعاد. فهي عبر الآلية الثلاثية لتصنيف التصاريح، والعتبات التقنية، والوقاية من التلوث وضبطه، تضمن أن يسير سلوك العبور دائماً على مسار «التأثير المنخفض، والقابلية للتتبع، والمساءلة». الهدف الأسمى للقواعد ليس تقييد التبادل بين الحضارات، بل جعل التبادل يحدث على نحو تكافلي، لا على نحو افتراسي.</p><h2 id="الوثائق-ذات-الصلة" tabindex="-1">الوثائق ذات الصلة <a class="header-anchor" href="#الوثائق-ذات-الصلة" aria-label="Permalink to &quot;الوثائق ذات الصلة&quot;">​</a></h2><ul><li>80-位面理论与分类 (نظرية الأبعاد وتصنيفها)</li><li>88-跨位面伦理准则 (المعايير الأخلاقية عبر الأبعاد)</li><li>62-空间法理技术实现 (الإدراك التقني للمبادئ القانونية المكانية)</li></ul>',23)])])}const b=a(l,[["render",i]]);export{c as __pageData,b as default};
